SELECT ProductId,PictureId,DisplayOrder FROM Product_Picture_Mapping WHERE ProductId IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0)) ORDER BY ProductId,DisplayOrder,Id
